document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("catalogGrid");if(!e)return;const t=IRWR_RECORDS.filter(e=>e.featured);e.innerHTML=t.map((e,t)=>`\n    <div class="ccard reveal in" data-id="${IRWR.escapeHtml(e.id)}">\n      <div class="cph"><img class="photo" src="${IRWR.photoUrl(e,"",700,700)}" alt="${IRWR.escapeHtml(e.title)}" loading="${t<3?"eager":"lazy"}" width="700" height="700"></div>\n      <div class="ctags"><span class="ctag">${IRWR.escapeHtml(e.category)}</span><span class="ctag">Verified</span></div>\n      <div class="cbottom">\n        <h3>${IRWR.escapeHtml(e.title)}</h3>\n        <p>${IRWR.escapeHtml(e.description)}</p>\n        <div class="crow"><a href="holders.html?holder=${encodeURIComponent(e.holderName)}" class="btn-line">Holder profile</a><button type="button" class="btn-gold" data-ripple data-view-entry>View entry</button></div>\n      </div>\n    </div>\n  `).join(""),e.addEventListener("click",e=>{if(e.target.closest("a"))return;const t=e.target.closest(".ccard");if(!t)return;const a=IRWR.byId(t.dataset.id);a&&IRWR.openRecordModal(a)})});